document.documentElement.classList.add('js');
const menu=document.querySelector('#menu'),nav=document.querySelector('#navigation');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e))}else document.querySelectorAll('.reveal').forEach(e=>e.classList.add('visible'));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-category]').forEach(p=>{p.hidden=b.dataset.filter!=='all'&&p.dataset.category!==b.dataset.filter})}));
const dialog=document.querySelector('#project-dialog'),projects={casa:{title:'Casa entre jardines',image:'assets/architecture.jpg',alt:'Visualización conceptual de una vivienda',description:'Una exploración de vivienda contemporánea abierta al paisaje. Imagen ilustrativa generada con IA para esta muestra; no representa una obra del estudio.'},materia:{title:'Materia y luz',image:'assets/diego-robalino.jpeg',alt:'Imagen de identidad aportada para Diego Robalino Architecture',description:'Referencia visual de la identidad compartida: madera oscura, formas escultóricas y materiales cálidos. No se presenta como un proyecto ejecutado por el estudio.'}};
document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{const p=projects[b.dataset.project];document.querySelector('#dialog-title').textContent=p.title;const img=document.querySelector('#dialog-image');img.src=p.image;img.alt=p.alt;document.querySelector('#dialog-description').textContent=p.description;dialog.showModal()}));document.querySelector('#close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelector('#consultation').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const values=new FormData(form),message='Hola, Diego Robalino Architecture. Soy '+values.get('name').trim()+'. Me interesa: '+values.get('service')+'.\n\n'+values.get('message').trim();const url='https://wa.me/593986865237?text='+encodeURIComponent(message);const link=document.querySelector('#ready');link.href=url;link.hidden=false;window.open(url,'_blank','noopener,noreferrer')});